const { completedSince, limit } = $.input;
const params = {};
if (completedSince) params.completed_since = completedSince;
params.limit = String(Math.max(1, Math.min(100, limit || 50)));
params.opt_fields = 'gid,name,assignee,assignee.name,due_on,completed,completed_at,notes,tags,tags.name,permalink_url,memberships.section.name';
return { params };

const resp = $.steps.listTasks.response || {};
const tasks = (resp.data || []).map(t => ({
  gid: t.gid,
  name: t.name,
  assignee: t.assignee ? (t.assignee.name || t.assignee.gid) : 'unassigned',
  dueOn: t.due_on || null,
  completed: !!t.completed,
  completedAt: t.completed_at || null,
  section: t.memberships && t.memberships[0] && t.memberships[0].section ? t.memberships[0].section.name : null,
  tags: (t.tags || []).map(tag => tag.name || tag.gid),
  permalink: t.permalink_url || '',
  notes: t.notes ? t.notes.substring(0, 200) : ''
}));

const open = tasks.filter(t => !t.completed).length;
const done = tasks.filter(t => t.completed).length;

return {
  tasks,
  totalCount: tasks.length,
  openCount: open,
  completedCount: done,
  projectGid: $.input.projectGid,
  hasMore: !!resp.next_page,
  summary: `Found ${tasks.length} task${tasks.length === 1 ? '' : 's'} (${open} open, ${done} completed)`
};
